wrong.source:
on(release){
   if(_global.quizTryCount == 1)
   {
      _global.WrongFeed = "The y-intercept is the constant term, when written in slope-intercept form.";
   }
   else
   {
      _global.WrongFeed = "The y-intercept is the constant term, when written in slope-intercept form. Try again.";
   }
   _root.disableQuizButton();
   Mc_Wrong_Feed4.gotoAndPlay(2);
   NMHBtn.enabled = false;
}

coachOpen.source:
on(release){
   NMHBtn.enabled = false;
   _root.disableQuizButton();
   Mc_Popup._visible = true;
   CloseBtn._visible = true;
}

coachClose.source:
on(release){
   NMHBtn.enabled = true;
   _root.enableQuizButton();
   Mc_Popup._visible = false;
   CloseBtn._visible = false;
}

wrongClose.source:
on(release){
   _parent.gotoAndPlay(21);
   i = 1;
   while(i <= 4)
   {
      eval("AnsBtn" + i).gotoAndStop(1);
      i++;
   }
}

quizStop.source:
stop();
_global.quizSection = true;
_global.quizTryCount = 0;
Mc_Popup._visible = false;
CloseBtn._visible = false;
